import{_ as r,a0 as i,w as a,s as n,I as o,x as e,a1 as p,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"對 DBA 最重要的 PostgreSQL 10 新亮點 | LCTT x X-CMD","titleTemplate":false,"description":"對 DBA 最重要的 PostgreSQL 10 新亮點 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"對 DBA 最重要的 PostgreSQL 10 新亮點 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"對 DBA 最重要的 PostgreSQL 10 新亮點 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171013 Best of PostgreSQL 10 for the DBA","title":"對 DBA 最重要的 PostgreSQL 10 新亮點","tag":"201711","desc":""},"relativePath":"201711/20171013 Best of PostgreSQL 10 for the DBA.md","filePath":"[post].md"}'),g={name:"201711/20171013 Best of PostgreSQL 10 for the DBA.md"};function f(u,t,m,w,b,B){const s=i("Link");return a(),n("div",null,[t[26]||(t[26]=o("h1",{id:"對-dba-最重要的-postgresql-10-新亮點",tabindex:"-1"},[e("對 DBA 最重要的 PostgreSQL 10 新亮點 "),o("a",{class:"header-anchor",href:"#對-dba-最重要的-postgresql-10-新亮點","aria-label":"Permalink to “對 DBA 最重要的 PostgreSQL 10 新亮點”"},"​")],-1)),o("p",null,[t[6]||(t[6]=e("前段時間新的重大版本的 PostgreSQL 10 發佈了！ 強烈建議閲讀",-1)),p(s,{href:"https://www.postgresql.org/about/news/1786/"},{default:l(()=>[...t[0]||(t[0]=[e("公告",-1)])]),_:1}),t[7]||(t[7]=e("、",-1)),p(s,{href:"https://www.postgresql.org/docs/current/static/release-10.html"},{default:l(()=>[...t[1]||(t[1]=[e("發佈説明",-1)])]),_:1}),t[8]||(t[8]=e("和“",-1)),p(s,{href:"https://wiki.postgresql.org/wiki/New_in_postgres_10"},{default:l(()=>[...t[2]||(t[2]=[e("新功能",-1)])]),_:1}),t[9]||(t[9]=e("”概述可以在",-1)),p(s,{href:"https://www.postgresql.org/about/news/1786/"},{default:l(()=>[...t[3]||(t[3]=[e("這裏",-1)])]),_:1}),t[10]||(t[10]=e("、",-1)),p(s,{href:"https://www.postgresql.org/docs/current/static/release-10.html"},{default:l(()=>[...t[4]||(t[4]=[e("這裏",-1)])]),_:1}),t[11]||(t[11]=e("和",-1)),p(s,{href:"https://wiki.postgresql.org/wiki/New_in_postgres_10"},{default:l(()=>[...t[5]||(t[5]=[e("這裏",-1)])]),_:1}),t[12]||(t[12]=e("。像往常一樣，已經有相當多的Blog覆蓋了所有新的東西，但我猜每個人都有自己認為重要的角度，所以與 9.6 版一樣我再次在這裏列出我印象中最有趣/相關的功能。",-1))]),t[27]||(t[27]=d(`<p>與往常一樣，升級或初始化一個新集羣的用户將獲得更好的性能（例如，更好的並行索引掃描、合併 join 和不相關的子查詢，更快的聚合、遠程服務器上更加智能的 join 和聚合），這些都開箱即用，但本文中我想講一些不能開箱即用，實際上你需要採取一些步驟才能從中獲益的內容。下面重點展示的功能是從 DBA 的角度來彙編的，很快也有一篇文章從開發者的角度講述更改。</p><h3 id="升級注意事項" tabindex="-1">升級注意事項 <a class="header-anchor" href="#升級注意事項" aria-label="Permalink to “升級注意事項”">​</a></h3><p>首先有些從現有設置升級的提示 - 有一些小的事情會導致從 9.6 或更舊的版本遷移時引起問題，所以在真正的升級之前，一定要在單獨的副本上測試升級，並遍歷發行説明中所有可能的問題。最值得注意的缺陷是：</p><ul><li><p>所有包含 “xlog” 的函數都被重命名為使用 “wal” 而不是 “xlog”。</p><p>後一個命名可能與正常的服務器日誌混淆，因此這是一個“以防萬一”的更改。如果使用任何第三方備份/複製/HA 工具，請檢查它們是否為最新版本。</p></li><li><p>存放服務器日誌（錯誤消息/警告等）的 pg_log 文件夾已重命名為 “log”。</p><p>確保驗證你的日誌解析或 grep 腳本（如果有）可以工作。</p></li><li><p>默認情況下，查詢將最多使用 2 個後台進程。</p><p>如果在 CPU 數量較少的機器上在 <code>postgresql.conf</code> 設置中使用默認值 <code>10</code>，則可能會看到資源使用率峯值，因為默認情況下並行處理已啓用 - 這是一件好事，因為它應該意味着更快的查詢。如果需要舊的行為，請將 <code>max_parallel_workers_per_gather</code> 設置為 <code>0</code>。</p></li><li><p>默認情況下，本地主機的複製連接已啓用。</p><p>為了簡化測試等工作，本地主機和本地 Unix 套接字複製連接現在在 <code>pg_hba.conf</code> 中以“<ruby>信任<rt>trust</rt></ruby>”模式啓用（無密碼）！因此，如果其他非 DBA 用户也可以訪問真實的生產計算機，請確保更改配置。</p></li></ul><h3 id="從-dba-的角度來看我的最愛" tabindex="-1">從 DBA 的角度來看我的最愛 <a class="header-anchor" href="#從-dba-的角度來看我的最愛" aria-label="Permalink to “從 DBA 的角度來看我的最愛”">​</a></h3><ul><li><p>邏輯複製</p><p>這個期待已久的功能在你只想要複製一張單獨的表、部分表或者所有表時只需要簡單的設置而性能損失最小，這也意味着之後主要版本可以零停機升級！歷史上（需要 Postgres 9.4+），這可以通過使用第三方擴展或緩慢的基於觸發器的解決方案來實現。對我而言這是 10 最好的功能。</p></li><li><p>聲明分區</p><p>以前管理分區的方法通過繼承並創建觸發器來把插入操作重新路由到正確的表中，這一點很煩人，更不用説性能的影響了。目前支持的是 “range” 和 “list” 分區方案。如果有人在某些資料庫引擎中缺少 “哈希” 分區，則可以使用帶表達式的 “list” 分區來實現相同的功能。</p></li><li><p>可用的哈希索引</p><p>哈希索引現在是 WAL 記錄的，因此是崩潰安全的，並獲得了一些性能改進，對於簡單的搜索，它們比在更大的數據上的標準 B 樹索引快。也支持更大的索引大小。</p></li><li><p>跨列優化器統計</p><p>這樣的統計數據需要在一組表的列上手動創建，以指出這些值實際上是以某種方式相互依賴的。這將能夠應對計劃器認為返回的數據很少（概率的乘積通常會產生非常小的數字）從而導致在大量數據下性能不好的的慢查詢問題（例如選擇“嵌套循環” join）。</p></li><li><p>副本上的並行快照</p><p>現在可以在 pg_dump 中使用多個進程（<code>-jobs</code> 標誌）來極大地加快備用服務器上的備份。</p></li><li><p>更好地調整並行處理 worker 的行為</p><p>參考 <code>max_parallel_workers</code> 和 <code>min_parallel_table_scan_size</code>/<code>min_parallel_index_scan_size</code> 參數。我建議增加一點後兩者的默認值（8MB、512KB）。</p></li><li><p>新的內置監控角色，便於工具使用</p><p>新的角色 <code>pg_monitor</code>、<code>pg_read_all_settings</code>、<code>pg_read_all_stats</code> 和 <code>pg_stat_scan_tables</code> 能更容易進行各種監控任務 - 以前必須使用超級用户帳户或一些 SECURITY DEFINER 包裝函數。</p></li><li><p>用於更安全的副本生成的臨時 (每個會話) 複製槽</p></li><li><p>用於檢查 B 樹索引的有效性的一個新的 Contrib 擴展</p><p>這兩個智能檢查發現結構不一致和頁面級校驗未覆蓋的內容。希望不久的將來能更加深入。</p></li><li><p>Psql 查詢工具現在支持基本分支（<code>if</code>/<code>elif</code>/<code>else</code>）</p><p>例如下面的將啓用具有特定版本分支（對 pg_stat* 視圖等有不同列名）的單個維護/監視腳本，而不是許多版本特定的腳本。</p></li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT :VERSION_NAME = &#39;10.0&#39; AS is_v10 \\gset </span></span>
<span class="line"><span>\\if :is_v10</span></span>
<span class="line"><span>    SELECT &#39;yippee&#39; AS msg;</span></span>
<span class="line"><span>\\else</span></span>
<span class="line"><span>    SELECT &#39;time to upgrade!&#39; AS msg;</span></span>
<span class="line"><span>\\endif</span></span></code></pre></div><p>這次就這樣了！當然有很多其他的東西沒有列出，所以對於專職 DBA，我一定會建議你更全面地看發佈記錄。非常感謝那 300 多為這個版本做出貢獻的人！</p><hr>`,9)),o("p",null,[t[14]||(t[14]=e("via: ",-1)),p(s,{href:"http://www.cybertec.at/best-of-postgresql-10-for-the-dba/"},{default:l(()=>[...t[13]||(t[13]=[e("http://www.cybertec.at/best-of-postgresql-10-for-the-dba/",-1)])]),_:1})]),o("p",null,[t[18]||(t[18]=e("作者：",-1)),p(s,{href:"http://www.cybertec.at/author/kaarel-moppel/"},{default:l(()=>[...t[15]||(t[15]=[e("Kaarel Moppel",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),p(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[16]||(t[16]=[e("geekpi",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),p(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[23]||(t[23]=e("本文由 ",-1)),p(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),p(s,{href:"https://linux.cn/"},{default:l(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const L=r(g,[["render",f]]);export{A as __pageData,L as default};
